def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    dangerous_pressure = 0.0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                bid = float(prev['bid'])
                prev_bids.append(bid)
                req = float(opp.get('water_requirement', WATER_REQ))
                sal = float(opp.get('daily_salary', DAILY_SALARY))
                pressure = bid / max(1.0, sal)
                if opp.get('no_water_days', 0) >= 2 or opp.get('hp', 10) <= 3:
                    pressure += 0.12
                if req >= WATER_REQ:
                    pressure += 0.03
                dangerous_pressure = max(dangerous_pressure, pressure)

    if not alive_opponents:
        if no_water >= 2 or hp <= 3:
            return float(min(budget, 40.0))
        return float(min(budget, 12.0))

    slots = max(1, int(supply // WATER_REQ))
    alive_count = len(alive_opponents) + 1
    competition = alive_count - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0

    if no_water >= 2 or hp <= 2:
        emergency = 72.0
        if highest_prev > 0:
            emergency = max(emergency, min(79.0, highest_prev + 2.0))
        return float(min(budget, emergency))

    if slots >= alive_count:
        if no_water >= 1:
            return float(min(budget, 18.0))
        return float(min(budget, 8.0))

    if competition <= 1:
        base = 24.0 if supply >= 22 else 30.0
        if dangerous_pressure >= 0.8:
            base = max(base, min(58.0, highest_prev + 1.5))
        elif highest_prev > 0:
            base = max(base, min(42.0, highest_prev * 0.72 + 1.0))
        if no_water >= 1:
            base += 10.0
        if hp <= 4:
            base += 8.0
        return float(min(budget, base))

    base = 34.0
    if supply <= 17:
        base = 46.0
    elif supply <= 19:
        base = 40.0

    if dangerous_pressure >= 0.95:
        base = max(base, 56.0)
    elif dangerous_pressure >= 0.8:
        base = max(base, 49.0)
    elif highest_prev > 0:
        base = max(base, min(50.0, highest_prev * 0.78 + 1.0))

    if no_water >= 1:
        base += 12.0
    if hp <= 4:
        base += 8.0

    reserve_floor = max(0.0, (10 - day) * 6.0)
    bid = min(base, budget)
    if budget - bid < reserve_floor and no_water == 0 and hp > 3:
        bid = max(18.0, budget - reserve_floor)
    if bid < 0:
        bid = 0.0
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid just enough to get water, save budget.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Determine a base bid if no strong history or for the first day
    base_bid = DAILY_SALARY * 0.55 

    # Adjust bid based on yesterday's highest bid
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        # If the highest previous bid was very aggressive
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3: 
                base_bid = DAILY_SALARY * 0.3 
            else: 
                base_bid = DAILY_SALARY * 0.95 
        else: # Moderate highest previous bid
            # Try to outbid the highest previous bid by a small margin, but not too low
            base_bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)

    # If no yesterday bids (e.g., day 1 or all opponents died yesterday)
    else:
        if my_status['hp'] <= 2: 
            base_bid = DAILY_SALARY * 0.9 
        else:
            base_bid = DAILY_SALARY * 0.55 

    # Final bid should not exceed current budget or daily salary
    final_bid = min(my_status['budget'], DAILY_SALARY, base_bid)

    # Ensure bid is at least 1 if I really need water and have budget
    if my_status['no_water_days'] > 0 and final_bid == 0 and my_status['budget'] > 0:
        final_bid = min(my_status['budget'], 1)

    # If it's the last day and I need water, bid aggressively if budget allows
    if day_context['day'] == EPISODE_DAYS - 1 and my_status['hp'] < WATER_REQ:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.99)

    # If budget is very low but HP is not critical, make a minimal bid
    if my_status['budget'] < DAILY_SALARY * 0.1 and my_status['hp'] > 1:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.1)

    # Ensure bid is not negative
    return max(0.0, final_bid)

def get_bid(day_context, my_status, opponents_status):
